package com.digitalhealth.dto;
import jakarta.validation.constraints.*; import java.time.LocalDate;
public class ConsentDTO {private Long id;@NotBlank private String provider;@NotNull private LocalDate grantedDate;private LocalDate expiryDate;@NotBlank private String purpose;private String status;public Long getId(){return id;}public void setId(Long x){id=x;}public String getProvider(){return provider;}public void setProvider(String x){provider=x;}public LocalDate getGrantedDate(){return grantedDate;}public void setGrantedDate(LocalDate x){grantedDate=x;}public LocalDate getExpiryDate(){return expiryDate;}public void setExpiryDate(LocalDate x){expiryDate=x;}public String getPurpose(){return purpose;}public void setPurpose(String x){purpose=x;}public String getStatus(){return status;}public void setStatus(String x){status=x;}}
